<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import http from '../api/http'
const data=ref(null), doctors=ref([]), form=ref({doctorId:null,visitDate:new Date().toISOString().slice(0,10)}), confirm=ref(false), preview=ref(null)
const registrationPage=ref(1), prescriptionPage=ref(1), pageSize=5
const load=async()=>{data.value=await http.get('/patient-portal/overview');doctors.value=await http.get('/patient-portal/doctors')}
const doctor=computed(()=>doctors.value.find(x=>x.id===form.value.doctorId))
const statusLabel=s=>({WAITING:'待接诊',IN_PROGRESS:'接诊中',COMPLETED:'已完成',CANCELLED:'已取消',UNPAID:'待缴费',PAID:'药房配药中',DISPENSED:'可取药',PICKED_UP:'已取药'}[s]||s)
const gender=x=>x==='MALE'?'男':'女'
const registrations=computed(()=>data.value?.registrations||[])
const prescriptions=computed(()=>data.value?.prescriptions||[])
const registrationRows=computed(()=>registrations.value.slice((registrationPage.value-1)*pageSize,registrationPage.value*pageSize))
const prescriptionRows=computed(()=>prescriptions.value.slice((prescriptionPage.value-1)*pageSize,prescriptionPage.value*pageSize))
const clampPage=(page,total)=>Math.min(page.value,Math.max(1,Math.ceil(total/pageSize)))
watch(registrations,rows=>registrationPage.value=clampPage(registrationPage,rows.length))
watch(prescriptions,rows=>prescriptionPage.value=clampPage(prescriptionPage,rows.length))
const prepare=async()=>{if(!form.value.doctorId)return ElMessage.warning('请先选择医生');preview.value=await http.get('/patient-portal/queue-preview',{params:form.value});confirm.value=true}
const register=async()=>{await http.post('/patient-portal/registrations',form.value);confirm.value=false;ElMessage.success('挂号成功，已加入候诊队列');await load()}
const pay=async row=>{try{await ElMessageBox.confirm(`确认支付收费订单 ${row.prescriptionNo}，金额 ¥${Number(row.totalAmount).toFixed(2)}？`,'确认支付',{confirmButtonText:'确认支付',cancelButtonText:'暂不支付',type:'warning'});await http.post(`/patient-portal/prescriptions/${row.id}/pay`);ElMessage.success('支付成功，药房将为您配药');await load()}catch(e){if(e==='cancel'||e==='close')return}}
const pickUp=async row=>{try{await ElMessageBox.confirm(`确认已领取处方 ${row.prescriptionNo} 的药品？`,'确认取药',{confirmButtonText:'确认已取药',cancelButtonText:'暂不确认',type:'success'});await http.post(`/patient-portal/prescriptions/${row.id}/pickup`);ElMessage.success('已确认取药，祝您早日康复');await load()}catch(e){if(e==='cancel'||e==='close')return}}
onMounted(load)
const refreshTimer=window.setInterval(load,30000)
onBeforeUnmount(()=>window.clearInterval(refreshTimer))
</script>
<template><div v-if="data" class="portal"><div class="portal-head"><div><h2>您好，{{data.patient.name}}</h2><p>{{gender(data.patient.gender)}} · {{data.patient.patientNo}}</p></div><el-button @click="load">刷新</el-button></div><div class="portal-primary"><el-card class="registration-card" header="自助挂号"><el-form label-position="top"><el-form-item label="选择医生"><el-select v-model="form.doctorId" style="width:100%"><el-option v-for="d in doctors" :key="d.id" :value="d.id" :label="`${d.departmentName} · ${d.realName}（${d.title}）`"/></el-select></el-form-item><el-form-item label="就诊日期"><el-date-picker v-model="form.visitDate" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item><el-button type="primary" @click="prepare">下一步</el-button></el-form></el-card><el-card class="notification-card"><template #header><div class="card-title">取药通知 <small>仅展示最新通知</small></div></template><el-scrollbar v-if="data.notifications.length" class="notification-list"><el-timeline><el-timeline-item v-for="n in data.notifications" :key="n.id" type="success" :timestamp="n.createdAt"><b>{{n.title}}</b><p>{{n.content}}</p></el-timeline-item></el-timeline></el-scrollbar><el-empty v-else :image-size="84" description="药房完成发药后，取药通知会显示在这里"/></el-card></div><div class="portal-records"><el-card class="record-card"><template #header><div class="card-title">我的挂号 <small>每 30 秒自动更新</small></div></template><el-table :data="registrationRows" height="326" table-layout="auto"><el-table-column prop="visitDate" label="日期" min-width="112"/><el-table-column prop="departmentName" label="科室" min-width="96"/><el-table-column prop="doctorName" label="医生" min-width="92"/><el-table-column label="候诊" min-width="110"><template #default="s"><span v-if="s.row.status==='WAITING'" class="queue-number">前方 {{s.row.queueAhead}} 人</span><span v-else>—</span></template></el-table-column><el-table-column label="状态" min-width="100"><template #default="s"><el-tag :type="s.row.status==='WAITING'?'warning':'success'">{{statusLabel(s.row.status)}}</el-tag></template></el-table-column></el-table><div class="table-footer"><span>共 {{registrations.length}} 条挂号记录</span><el-pagination v-if="registrations.length>pageSize" v-model:current-page="registrationPage" :page-size="pageSize" layout="prev, pager, next" :total="registrations.length"/></div></el-card><el-card class="record-card prescription-card"><template #header><div class="card-title">我的处方 <small>医院开具处方后会生成收费订单</small></div></template><el-table :data="prescriptionRows" height="326" table-layout="auto"><el-table-column prop="prescriptionNo" label="处方号" min-width="190"/><el-table-column label="状态" min-width="120"><template #default="s">{{statusLabel(s.row.status)}}</template></el-table-column><el-table-column label="金额" min-width="110"><template #default="s">¥{{Number(s.row.totalAmount).toFixed(2)}}</template></el-table-column><el-table-column label="操作" min-width="140"><template #default="s"><el-button v-if="s.row.status==='UNPAID'" type="primary" size="small" @click="pay(s.row)">立即支付</el-button><el-button v-else-if="s.row.status==='DISPENSED'" type="success" size="small" @click="pickUp(s.row)">确认已取药</el-button><span v-else>—</span></template></el-table-column></el-table><div class="table-footer"><span>共 {{prescriptions.length}} 条处方记录</span><el-pagination v-if="prescriptions.length>pageSize" v-model:current-page="prescriptionPage" :page-size="pageSize" layout="prev, pager, next" :total="prescriptions.length"/></div></el-card></div><el-dialog v-model="confirm" title="确认挂号" width="min(460px, calc(100vw - 32px))"><div v-if="preview" class="confirm"><div><span>就诊科室</span><b>{{doctor?.departmentName}}</b></div><div><span>就诊医生</span><b>{{doctor?.realName}} · {{doctor?.title}}</b></div><div><span>就诊日期</span><b>{{form.visitDate}}</b></div><div class="queue"><span>您前面候诊人数</span><strong>{{preview.aheadCount}} <small>人</small></strong><p>该人数包含待接诊和正在接诊的患者，实际等待时间以现场叫号为准。</p></div></div><template #footer><el-button @click="confirm=false">返回修改</el-button><el-button type="primary" @click="register">确认挂号</el-button></template></el-dialog></div><el-skeleton v-else :rows="6" animated/></template>
<style scoped>.portal{max-width:1360px;margin:auto}.portal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.portal-head h2{margin:0;color:#183b67}.portal-head p,.el-timeline p{color:#71839a}.portal-primary,.portal-records{display:grid;gap:20px;margin-bottom:20px}.portal-primary{grid-template-columns:minmax(330px,.72fr) minmax(500px,1.28fr)}.portal-records{grid-template-columns:minmax(520px,1fr) minmax(620px,1.3fr)}.registration-card,.notification-card{min-height:426px}.registration-card :deep(.el-card__body){display:flex;align-items:center;min-height:349px}.registration-card :deep(.el-form){width:100%;max-width:440px}.notification-card :deep(.el-card__body){padding-right:12px}.notification-list{height:344px;padding-right:10px}.notification-list :deep(.el-timeline){margin:3px 0 0 8px}.notification-list :deep(.el-timeline-item){padding-bottom:19px}.notification-list :deep(.el-timeline-item:last-child){padding-bottom:0}.notification-list :deep(.el-timeline-item__timestamp){margin-bottom:5px}.notification-list p{margin:6px 0 0;line-height:1.6}.record-card{min-width:0}.record-card :deep(.el-card__body){padding-bottom:16px}.table-footer{display:flex;min-height:40px;align-items:end;justify-content:space-between;gap:12px;padding-top:14px;color:#71839a;font-size:13px}.queue-number{color:#1d4e89;font-weight:700;white-space:nowrap}.confirm{display:grid;gap:16px}.confirm>div{display:flex;justify-content:space-between;gap:20px}.confirm span{color:#71839a}.queue{margin-top:8px;padding-top:18px;border-top:1px solid #e8eef5;align-items:flex-start!important;flex-wrap:wrap}.queue strong{font-size:28px;color:#1d4e89}.queue small,.card-title small{font-size:13px;font-weight:400;color:#71839a}.queue p{width:100%;margin:0;color:#71839a;font-size:13px;line-height:1.6}.card-title{display:flex;gap:10px;align-items:baseline}.card-title small{white-space:nowrap}@media(max-width:1100px){.portal-primary,.portal-records{grid-template-columns:1fr}.registration-card,.notification-card{min-height:0}.registration-card :deep(.el-card__body){min-height:0}.registration-card :deep(.el-form){max-width:none}}@media(max-width:600px){.portal-head{align-items:flex-start;gap:12px}.card-title{display:block}.card-title small{display:block;margin-top:3px}.table-footer{align-items:flex-start;flex-direction:column}.record-card :deep(.el-table__body-wrapper){overflow-x:auto}.notification-list{height:300px}}</style>
